// movement-run.bml — a whole movement of the rent path in one native call.
//
// One process, one census window, no child kernel: the body composes its own
// answer and floors it (form-stdlib/bml/form-cli-native-compare.bml), speaks
// that composition through its own model session on this metal, wearing its
// own trained adapter when the caller names the lora lane
// (form-stdlib/bml/form-cli-voice-walk.bml), reads the arriving mind's flow
// (form-stdlib/bml/form-cli-flow-meter.bml), redraws the page from the
// ledgers (form-stdlib/bml/form-cli-rent-ladder-page.bml) and lands
// (form-stdlib/bml/form-cli-landing.bml: restart, gates, commit, push). The
// composition never travels through a pipe and the model is admitted once, in
// this call's own process. No provider is asked anywhere in it. The crossings
// that remain are the landing's: git, and the drift gates in their own fresh
// kernel so a warm image cannot vouch for the tree. The arriving mind makes
// one call and relays one line; every crossing is counted and printed.
//
// stdin: one JSON object, every field optional
//   {"movement":"<name>", "voice":1, "compare":1, "transcript":"<path or empty>",
//    "lane":"lora", "adapter":"<dir>", "model":"qwen38-q8", "max_reply_tokens":1536,
//    "land":1, "restart":"", "paths":["extra", ...], "subject":"...", "body":"..."}
// preflight-exec: forbidden
// preludes: form-stdlib/bml/form-cli-heal-native-report.bml form-stdlib/meaning-codes.bml form-stdlib/bml/form-cli-voice-walk.bml form-stdlib/bml/form-cli-flow-meter.bml form-stdlib/bml/form-cli-rent-ladder-page.bml form-stdlib/bml/form-cli-landing.bml observe/form-membrane-runtime-census.fk
section [form.bml] {
 class Movement {
  def mv-source() = "observe/movement-run.bml";
  def mv-str(doc, key) = if json-object-has?(doc, key) then json-string-value(json-object-get(doc, key)) else "";
  def mv-int(doc, key) = if json-object-has?(doc, key) then json-int-value(json-object-get(doc, key)) else 0;
  def mv-flag(doc, key, fallback) = if json-object-has?(doc, key) then eq(json-int-value(json-object-get(doc, key)), 1) else fallback;
  def mv-values(doc, key) = if json-object-has?(doc, key) then oh-values(json-array-elements(json-object-get(doc, key))) else list();
  def mv-nodes(xs) = if nil?(xs) then list() else cons(json-node-string(head(xs)), mv-nodes(tail(xs)));
  def mv-first-line(text) { let at = str_find(text, "\n", 0); if lt(at, 0) then text else substring(text, 0, at); }
  def mv-doc(text) = if str_eq(trim(text), "") then json-node-object(list()) else parse-json("child-line", mv-first-line(text));
  def mv-row(doc) = if json-object-has?(doc, "row") then json-object-get(doc, "row") else json-node-object(list());
  def mv-grep-line(text, mark) { let at = str_find(text, mark, 0); if lt(at, 0) then "" else mv-first-line(substring(text, at, str_len(text))); }
  def mv-planes(planes, rows) = if nil?(planes) then "" else mc-cat(list(head(planes), "=", int_to_str(fmrc-delta-plane-total(rows, head(planes))), if nil?(tail(planes)) then "" else " ", mv-planes(tail(planes), rows)));
  def mv-plane-names() = list("stdio", "filesystem", "local-process", "network-address-unknown", "mesh");
  def mv-ledger-paths() = list("receipts/rent-ledger.jsonl", "receipts/parity-contest-ledger.jsonl", "receipts/flow-ledger.jsonl", "receipts/crossings-ledger.jsonl", "docs/rent-ladder.html");
  def mv-crossings() = "receipts/crossings-ledger.jsonl";
  // one row per movement, written after the census closes and before the page redraw and the landing, so the page draws it and the landing carries it; the page and landing child kernels come after the row and are not in it: the movement door's own planes and the voice and compare doors' dispatches, read from their printed census
  def mv-crossings-row(name, rows) = json-node-object(list(
   fhn-n("at_unix_ms", now_unix_ms()),
   fhn-s("movement", name),
   fhn-n("movement_dispatches", fmrc-delta-total(rows)),
   fhn-n("movement_stdio", fmrc-delta-plane-total(rows, "stdio")),
   fhn-n("movement_filesystem", fmrc-delta-plane-total(rows, "filesystem")),
   fhn-n("movement_local_process", fmrc-delta-plane-total(rows, "local-process")),
   fhn-n("movement_network", fmrc-delta-plane-total(rows, "network-address-unknown")),
   fhn-n("voice_dispatches", 0),
   fhn-n("voice_network", 0),
   fhn-n("compare_dispatches", 0),
   fhn-n("voice_and_compare_in_movement_window", 1)));
  def mv-with(doc, request, key) = if json-object-has?(request, key) then json-node-object(append(json-object-pairs(doc), list(json-node-pair(key, json-object-get(request, key))))) else doc;
  // Every door speaks its own state; the movement gathers what they said, keeps
  // it in the body's own spool and carries the count in its line, so one call
  // shows where healing is wanted without any gate standing in the way.
  def mv-health-spool() = ".form-heal/movement-health.jsonl";
  def mv-unease(readings) = if nil?(readings) then 0 else add(if oh-unease(head(readings)) then 1 else 0, mv-unease(tail(readings)));
  def mv-keep(readings) = if nil?(readings) then 0 else mv-keep(mv-kept(oh-emit(mv-health-spool(), head(readings)), tail(readings)));
  def mv-kept(emitted, rest) = rest;
  def mv-readings(voiceOut, flowOut, pageOut, landOut) = append(mv-slot(voiceOut, 3), append(mv-slot(flowOut, 2), append(mv-slot(pageOut, 1), mv-slot(landOut, 1))));
  def mv-slot(walked, i) = if or(nil?(walked), lt(len(walked), add(i, 1))) then list() else nth(walked, i);
  def mv-voice-request(name, composition, request) = mv-with(mv-with(mv-with(mv-with(if str_eq(composition, "") then json-node-object(list(fhn-s("movement", name))) else json-node-object(list(fhn-s("movement", name), fhn-s("composition", composition))), request, "lane"), request, "adapter"), request, "model"), request, "max_reply_tokens");
  // the voice and the compare run inside this call's own census window: one process, no pipe, no child kernel
  def mv-voice-walk(name, on, composition, request) = if on then nvw-walk(mv-voice-request(name, composition, request)) else list(json-node-object(list()), "", "", list());
  def mv-compare(on) = if on then fnc-walk() else list("", list(0, 0, 0, 0, 0), "");
  def mv-flow(name, transcript) = if str_eq(transcript, "") then list(json-node-object(list()), "", list()) else fm-reading(transcript, name);
  def mv-page() = rlp-walk();
  def mv-land-request(request, name) = json-node-object(list(
   fhn-s("restart", mv-str(request, "restart")),
   fhn-s("witness", ""),
   fhn-a("paths", mv-nodes(append(mv-ledger-paths(), mv-values(request, "paths")))),
   fhn-s("subject", if str_eq(mv-str(request, "subject"), "") then mc-cat(list("Movement ", name, ": rows and the redrawn ladder")) else mv-str(request, "subject")),
   fhn-s("body", if str_eq(mv-str(request, "body"), "") then "Walked by the body in one call (observe/movement-run.bml): the native voice through the in-process model, the native single call, the flow meter, the page redrawn from the ledgers." else mv-str(request, "body"))));
  def mv-land(request, name, on) = if on then ld-land(mv-land-request(request, name)) else list("", list());
  def mv-run() {
   let window = fmrc-open("movement", "voice compare flow page land", mv-source(), 1, 1);
   let line0 = read_line();
   let line = if nothing?(line0) then "" else trim(line0);
   let request = if str_eq(line, "") then json-node-object(list()) else parse-json("movement-request", line);
   let name = if str_eq(mv-str(request, "movement"), "") then "movement" else mv-str(request, "movement");
   let compared = mv-compare(mv-flag(request, "compare", true));
   let compare = fnc-floor-line(nth(compared, 1), nth(compared, 2));
   let voiceWalk = mv-voice-walk(name, mv-flag(request, "voice", true), nth(compared, 0), request);
   let voice = head(voiceWalk);
   let flowWalk = mv-flow(name, mv-str(request, "transcript"));
   let flow = head(flowWalk);
   let result0 = fmrc-close(window, "observed", mv-source(), 2, 1);
   let rows0 = fmrc-result-deltas(result0);
   let crossed = fhn-append(mv-crossings(), str_concat(json-emit(mv-crossings-row(name, rows0)), "\n"));
   let pageWalk = mv-page();
   let page = head(pageWalk);
   let landWalk = mv-land(request, name, mv-flag(request, "land", true));
   let landed = head(landWalk);
   let readings = mv-readings(voiceWalk, flowWalk, pageWalk, landWalk);
   let keptHealth = mv-keep(readings);
   let result = result0;
   let rows = rows0;
   print_str(json-emit-precise(json-node-object(list(
    fhn-s("movement", name),
    json-node-pair("voice", json-node-object(list(
     fhn-s("source", mv-str(voice, "source")),
     fhn-s("model", mv-str(voice, "oracle_model")),
     fhn-n("predicted", mv-int(voice, "oracle_tokens_predicted")),
     fhn-n("axes", mv-int(voice, "answer_axes")),
     fhn-n("receipts_cited", mv-int(voice, "answer_receipts_cited")),
     fhn-n("ms", mv-int(voice, "oracle_ms")),
     fhn-s("answer", mv-str(voice, "answer"))))),
    fhn-s("compare", compare),
    json-node-pair("flow", json-node-object(list(
     fhn-n("provider_calls", mv-int(flow, "provider_calls")),
     fhn-n("native_fkwu_calls", mv-int(flow, "native_fkwu_calls")),
     fhn-n("non_form_calls", mv-int(flow, "non_form_calls"))))),
    fhn-n("page_bytes", mv-int(page, "bytes")),
    fhn-s("landing", mv-grep-line(landed, "[landing]")),
    fhn-s("push", mv-grep-line(landed, "[push]")),
    json-node-pair("health", json-node-object(list(fhn-n("readings", len(readings)), fhn-n("unease", mv-unease(readings)), fhn-s("spool", mv-health-spool())))),
    fhn-s("census", fmrc-result-status(result)),
    fhn-n("dispatches", fmrc-delta-total(rows)),
    fhn-s("planes", mv-planes(mv-plane-names(), rows))))));
  }
 }
 mv-run();
}

// The voice walk: the body's own composition spoken by its own model session,
// retained as evidence and rowed in the rent ledger.
//
// The walk is a call, not a process: a caller that already holds a census
// window runs it inside that window, so the voice costs no child kernel and
// the composition never travels through a pipe. No model server, no provider.
// preludes: form-stdlib/bml/form-cli-native-compare.bml form-stdlib/bml/form-cli-native-voice.bml
section [form.bml] {
 class FormCliVoiceWalk {
  def nvw-ledger() = "receipts/rent-ledger.jsonl";
  def nvw-str(doc, key) = if json-object-has?(doc, key) then json-string-value(json-object-get(doc, key)) else "";
  def nvw-packet(composition) = mc-cat(list(
   read_file(fnc-enquiry()), "\n\n",
   "[The body's own measured answer follows. Every number in it is a row the body wrote.]\n",
   composition, "\n",
   "This turn has no tools and no file access; everything usable is in this message. Speak the comparison above in plain sentences, axis by axis in the order given, using its numbers and ledger rows, and say only what the composition states: add no judgment of your own, and where an axis carries no number or verdict, say so. Cite receipts by the paths given. After the answer, say plainly what the material does not establish and what remains pending.\n"));
  def nvw-row(options, job, packet, answer, floor, oracle, groundingMs, oracleMs) = json-node-object(list(
   fhn-n("at_unix_ms", now_unix_ms()),
   fhn-s("movement", if json-object-has?(options, "movement") then nvw-str(options, "movement") else "native-voice"),
   fhn-s("enquiry", fnc-enquiry()),
   fhn-s("source", if str_eq(nth(oracle, 0), "answered") then "fkwu-model-session" else "none"),
   json-node-pair("native_generation", fcnv-metadata(oracle)),
   fhn-s("oracle", nth(oracle, 0)),
   fhn-n("rent_tokens", 0),
   fhn-n("oracle_tokens_evaluated", nth(oracle, 2)),
   fhn-n("oracle_tokens_predicted", nth(oracle, 3)),
   fhn-s("oracle_model", nth(oracle, 4)),
   fhn-n("receipts_in_packet", fnc-receipt-limit()),
   fhn-n("packet_bytes", str_len(packet)),
   fhn-n("answer_bytes", str_len(answer)),
   fhn-n("answer_axes", nth(floor, 0)),
   fhn-n("answer_receipts_cited", nth(floor, 1)),
   fhn-n("answer_receipts_existing", nth(floor, 2)),
   fhn-n("answer_limits", nth(floor, 3)),
   fhn-n("grounding_ms", groundingMs),
   fhn-n("oracle_ms", oracleMs),
   fhn-n("provider_ms", 0),
   fhn-s("answer", fhn-at(job, "answer.md")),
   fhn-s("evidence", job)));
  // The walk speaks its own state as it goes: a session that did not answer is
  // a live reading with what it needs and what it offers, not a silent zero.
  def nvw-organ() = "native-voice";
  def nvw-flow(options) = if json-object-has?(options, "movement") then nvw-str(options, "movement") else "native-voice";
  def nvw-lane(options) = if json-object-has?(options, "lane") then nvw-str(options, "lane") else "registry-weights";
  def nvw-answered?(oracle) = str_eq(nth(oracle, 0), "answered");
  def nvw-needs(oracle, job) = if nvw-answered?(oracle) then list() else list(oh-need(nth(oracle, 7), json-node-string(job)));
  def nvw-reading(options, oracle, job) = oh-reading(nvw-organ(), nvw-flow(options), str_concat("model-session:", nvw-lane(options)), json-node-string("answered"), json-node-string(nth(oracle, 0)), json-node-int(if nvw-answered?(oracle) then 1 else 0), nvw-needs(oracle, job), list("registry-weights", "smaller-allowance", "inspect-native-evidence"), oh-reference(fhn-at(job, "answer.md")));
  // The one remedy the walk can apply itself: drop the adapter lane and let the
  // registry weights answer, then observe that attempt in its own right.
  def nvw-without-lane(options) = json-node-object(oh-without(json-object-pairs(options), "lane"));
  def nvw-heal(options, packet, job, oracle, reading) = if or(nvw-answered?(oracle), not(str_eq(nvw-lane(options), "lora"))) then list(oracle, list(reading)) else nvw-healed(options, job, reading, fcnv-ask(packet, nvw-without-lane(options)));
  def nvw-healed(options, job, reading, second) = list(second, list(reading, oh-applied(reading, "registry-weights", json-node-string(nth(second, 0))), nvw-reading(nvw-without-lane(options), second, job)));
  def nvw-keep(job, readings) = if nil?(readings) then 0 else nvw-keep(job, nvw-kept(oh-emit(fhn-at(job, "events.jsonl"), head(readings)), tail(readings)));
  def nvw-kept(emitted, rest) = rest;
  // Answers list(row, job, appended, readings): the ledger row, its evidence
  // directory, what the append wrote, and the health readings the walk spoke.
  def nvw-walk(options) {
   let started = now_unix_ms();
   let spool = fhn-at(fhn-root(), ".form-heal");
   let made = fs_mkdir(spool);
   let job = fhn-unique(spool, "native-voice-", 0);
   let composition = if json-object-has?(options, "composition") then nvw-str(options, "composition") else fnc-compose();
   let packet = nvw-packet(composition);
   let wrotePacket = write_file_text(fhn-at(job, "packet.txt"), packet);
   let grounded = now_unix_ms();
   let first = fcnv-ask(packet, options);
   let healed = nvw-heal(options, packet, job, first, nvw-reading(options, first, job));
   let oracle = nth(healed, 0);
   let readings = oh-voice-all(nth(healed, 1));
   let retained = fcnv-retain(job, oracle);
   let kept = nvw-keep(job, readings);
   let spoken = now_unix_ms();
   let answer = nth(oracle, 1);
   let wroteAnswer = write_file_text(fhn-at(job, "answer.md"), answer);
   let floor = apc-floor(answer);
   let row = nvw-row(options, job, packet, answer, floor, oracle, sub(grounded, started), sub(spoken, grounded));
   let appended = fhn-append(nvw-ledger(), str_concat(json-emit(row), "\n"));
   list(row, job, appended, readings);
  }
 }
}

def ld-land(request) {
 let restarted = ld-restart(ld-str(request, "restart"));
 let written = ld-write-all(ld-nodes(request, "files"));
 let appendedFiles = ld-append-all(ld-nodes(request, "append"));
 let misses = ld-edit-all(ld-nodes(request, "edits"), 0);
 let witness = ld-str(request, "witness");
 let paths = ld-paths(request);
 let subject = ld-str(request, "subject");
 let witnessOut0 = if str_eq(witness, "") then "" else host-exec(mc-cat(list(witness, " 2>&1")), "");
 let witnessOut = if nothing?(witnessOut0) then "" else witnessOut0;
 let gates0 = host-exec("./fkwu gate/drift-gates-run.bml 2>&1", "");
 let gates = if nothing?(gates0) then "" else gates0;
 let green = ge(str_find(gates, " refused=0 ", 0), 0);
 let ready = and(green, and(eq(misses, 0), and(not(nil?(paths)), not(str_eq(subject, "")))));
 // the message lives under .form-heal, which a fresh checkout does not have yet: make it before writing
 let spool = fs_mkdir(".form-heal");
 let saved0 = write_file_text(ld-message-path(), mc-cat(list(subject, "\n\n", ld-str(request, "body"), "\n")));
 let saved = if nothing?(saved0) then 0 else saved0;
 let added = if ready then host-exec(mc-cat(list("git add ", ld-join(ld-quoted(paths), " "), " 2>&1")), "") else "";
 let committed0 = if ready then host-exec(mc-cat(list("out=$(git -c user.name=Claude -c user.email=noreply@anthropic.com commit -q -F ", ld-message-path(), " 2>&1); code=$?; printf '[commit] exit=%s %s\\n' \"$code\" \"$(git log --oneline -1)\"")), "") else "";
 let committed = if nothing?(committed0) then "" else committed0;
 let commitOk = ge(str_find(committed, "[commit] exit=0", 0), 0);
 // the push answers with its own exit: a commit that did not reach origin is held, never landed
 let pushed0 = if commitOk then host-exec("out=$(git push -u origin HEAD 2>&1); code=$?; printf '[push] exit=%s %s\\n' \"$code\" \"$(printf '%s' \"$out\" | tail -n 1)\"", "") else "";
 let pushed = if nothing?(pushed0) then "" else pushed0;
 let pushOk = ge(str_find(pushed, "[push] exit=0", 0), 0);
 let why = ld-held-why(green, misses, paths, subject, ready, commitOk, pushOk);
 let readings = oh-voice-all(list(ld-health(subject, why, and(ready, and(commitOk, pushOk)))));
 list(mc-cat(list(
  if str_eq(witnessOut, "") then "" else mc-cat(list("[witness] ", witness, "\n", witnessOut, "\n")),
  if str_eq(restarted, "") then "" else mc-cat(list("[restart] ", restarted, "\n")),
  "[files] written=", int_to_str(written), " appended=", int_to_str(appendedFiles), " edit-misses=", int_to_str(misses), "\n",
  "[gates] ", ld-tail(gates, 120),
  "[landing] ", if and(ready, and(commitOk, pushOk)) then "landed" else if and(ready, commitOk) then "held: the push did not reach origin" else if ready then "held: the commit did not take" else if not(green) then "held: a gate refused" else if gt(misses, 0) then "held: an edit missed" else "held: no paths or no subject", "\n",
  if ready then mc-cat(list(added, committed, "\n", pushed, "\n")) else "")), readings);
}
